BEGIN; SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
LOCK TABLE tam_the_lookup_entries,calculation_rules,source_sections,source_books IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE career_import(rule text,key text,code text,title text,content text,table_page int,content_page int,table_label text,heading text,note text,PRIMARY KEY(rule,key,code)) ON COMMIT DROP;
DO $$ BEGIN
IF (SELECT count(*) FROM source_books WHERE id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in') AND file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d' AND pdf_page_count=360)<>1
 THEN RAISE EXCEPTION 'D01 wrong source edition'; END IF;
IF EXISTS(SELECT 1 FROM source_sections WHERE source_book_id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in')
 AND section_label='TT-CONG-DANH-13-TEXT' AND (pdf_page<>36 OR printed_page_label IS DISTINCT FROM '37'
 OR excerpt IS DISTINCT FROM 'D01: literal career passages 4-12; table labels and passage headings retained separately.'))
 THEN RAISE EXCEPTION 'D01 protected passage source changed'; END IF;
END $$;
 VALUES((SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in'),'TT-CONG-DANH-13-TEXT','37',36,'D01: literal career passages 4-12; table labels and passage headings retained separately.')
 ON CONFLICT(source_book_id,section_label,pdf_page) DO NOTHING;

DO $$ BEGIN
IF (SELECT count(*) FROM calculation_rules r JOIN source_sections s ON s.id=r.source_section_id
 WHERE r.module='TAM_THE' AND r.rule_code='TT-CONG-DANH-11' AND r.rule_version='1.0'
 AND s.source_book_id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in') AND s.section_label='TT-CONG-DANH-11' AND s.pdf_page=32
 AND s.printed_page_label='33' AND (
 (r.verification_status='SOURCE_LOCATED' AND r.reviewer IS NULL AND r.reviewed_at IS NULL AND r.verification_note IS NULL
 AND r.description='Bảng ngành nghề theo hành mệnh và tháng âm.') OR
 (r.verification_status='VERIFIED' AND r.reviewer='Codex career review 2026-10-24 (same-tool second pass)' AND r.reviewed_at IS NOT NULL
 AND r.verification_note='D01 PDF32/print33: all 51 positive occupation-month incidences reviewed twice; THUY/CAU_CHAI month8 corrects legacy month9. No-match is not a negative prediction. Same-tool review, not independent human TV2. Scope=CAREER11_TABLE; docs/25-D01-CAREER-DATA.md.' AND r.description='Số 11: tra mọi nghề có giao điểm hành mệnh + tháng âm tại PDF32/in33; 51 giao điểm đã kiểm nguồn D01.')))<>1
 THEN RAISE EXCEPTION 'D01 changed/protected career rule or source'; END IF;
END $$;
DO $$ BEGIN
IF (SELECT count(*) FROM calculation_rules r JOIN source_sections s ON s.id=r.source_section_id
 WHERE r.module='TAM_THE' AND r.rule_code='TT-CONG-DANH-13' AND r.rule_version='1.0'
 AND s.source_book_id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in') AND s.section_label='TT-CONG-DANH-13' AND s.pdf_page=35
 AND s.printed_page_label='36' AND (
 (r.verification_status='SOURCE_LOCATED' AND r.reviewer IS NULL AND r.reviewed_at IS NULL AND r.verification_note IS NULL
 AND r.description='Bảng 120 ô Can năm x tháng âm cần đối chiếu đủ.') OR
 (r.verification_status='VERIFIED' AND r.reviewer='Codex career review 2026-10-24 (same-tool second pass)' AND r.reviewed_at IS NOT NULL
 AND r.verification_note='D01 PDF35-36/print36-37: all 120 stem-month cells and 12 literal passages reviewed twice. Four differing table/passage headings are kept separately and linked by source ordinal (not asserted identical spelling). Source table lookup, no plus-stem shortcut. Same-tool review, not independent human TV2. Scope=CAREER13_TABLE_AND_TRANSCRIPTION; docs/25-D01-CAREER-DATA.md.' AND r.description='Số 13 nghề: tra tháng trong hàng Can năm âm tại PDF35/in36; 120 ô và 12 đoạn PDF35-36. Giữ riêng nhãn cột/đoạn và liên kết theo vị trí D01.')))<>1
 THEN RAISE EXCEPTION 'D01 changed/protected career rule or source'; END IF;
END $$;
DO $$ BEGIN
IF EXISTS(SELECT 1 FROM tam_the_lookup_entries e JOIN calculation_rules r ON r.id=e.rule_id
 LEFT JOIN career_import n ON n.rule=r.rule_code AND n.key=e.lookup_key AND n.code=e.result_code
 LEFT JOIN source_sections cs ON cs.id=e.content_source_section_id
 WHERE r.module='TAM_THE' AND r.rule_version='1.0' AND r.rule_code IN('TT-CONG-DANH-11','TT-CONG-DANH-13')
 AND NOT coalesce((r.rule_code='TT-CONG-DANH-11' AND e.lookup_key='ELEMENT:THUY|MONTH:09' AND e.result_code='CAU_CHAI'
 AND e.title='Câu/chài lưới/đáy rọ/mua thủy lợi' AND e.description IS NULL AND e.editor='AUTO_FROM_DOCS'
 AND e.verification_status='SOURCE_LOCATED' AND e.reviewer IS NULL AND e.reviewed_at IS NULL AND e.verification_note IS NULL
 AND e.source_section_id=r.source_section_id AND e.content_source_section_id IS NULL
 AND e.source_table_label IS NULL AND e.source_content_heading IS NULL),false) AND (n.key IS NULL
 OR e.title IS DISTINCT FROM n.title OR e.description IS DISTINCT FROM n.content
 OR e.source_section_id IS DISTINCT FROM r.source_section_id
 OR e.source_table_label IS DISTINCT FROM n.table_label OR e.source_content_heading IS DISTINCT FROM n.heading
 OR cs.pdf_page IS DISTINCT FROM n.content_page
 OR (n.content_page IS NOT NULL AND (cs.source_book_id IS DISTINCT FROM (SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in')
   OR cs.section_label IS DISTINCT FROM CASE WHEN n.content_page=35 THEN 'TT-CONG-DANH-13' ELSE 'TT-CONG-DANH-13-TEXT' END
   OR cs.printed_page_label IS DISTINCT FROM (n.content_page+1)::text))
 OR e.editor NOT IN ('AUTO_FROM_DOCS','TV3_AI_CAREER_SOURCE_D01_2026_10_24') OR e.editor IS NULL
 OR NOT ((e.verification_status='SOURCE_LOCATED' AND e.reviewer IS NULL AND e.reviewed_at IS NULL AND e.verification_note IS NULL)
 OR (e.verification_status='VERIFIED' AND e.reviewer='Codex career review 2026-10-24 (same-tool second pass)' AND e.reviewed_at IS NOT NULL AND e.verification_note=n.note))))
 THEN RAISE EXCEPTION 'D01 changed/protected career entry'; END IF;
END $$;
DELETE FROM tam_the_lookup_entries e USING calculation_rules r
 WHERE e.rule_id=r.id AND r.module='TAM_THE' AND r.rule_version='1.0' AND (r.rule_code='TT-CONG-DANH-11' AND e.lookup_key='ELEMENT:THUY|MONTH:09' AND e.result_code='CAU_CHAI'
 AND e.title='Câu/chài lưới/đáy rọ/mua thủy lợi' AND e.description IS NULL AND e.editor='AUTO_FROM_DOCS'
 AND e.verification_status='SOURCE_LOCATED' AND e.reviewer IS NULL AND e.reviewed_at IS NULL AND e.verification_note IS NULL
 AND e.source_section_id=r.source_section_id AND e.content_source_section_id IS NULL
 AND e.source_table_label IS NULL AND e.source_content_heading IS NULL);
 content_source_section_id,source_table_label,source_content_heading,verification_status,editor)
SELECT r.id,n.key,n.code,n.title,n.content,r.source_section_id,cs.id,n.table_label,n.heading,'SOURCE_LOCATED','TV3_AI_CAREER_SOURCE_D01_2026_10_24'
 FROM career_import n JOIN calculation_rules r ON r.module='TAM_THE' AND r.rule_code=n.rule AND r.rule_version='1.0'
 LEFT JOIN source_sections cs ON cs.source_book_id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in') AND cs.pdf_page=n.content_page
 AND cs.section_label=CASE WHEN n.content_page=35 THEN 'TT-CONG-DANH-13' ELSE 'TT-CONG-DANH-13-TEXT' END
ON CONFLICT(rule_id,lookup_key,result_code) DO NOTHING;
DO $$ BEGIN
IF (SELECT count(*) FROM tam_the_lookup_entries e JOIN calculation_rules r ON r.id=e.rule_id
 JOIN career_import n ON n.rule=r.rule_code AND n.key=e.lookup_key AND n.code=e.result_code
 WHERE r.module='TAM_THE' AND r.rule_version='1.0')<>171
 OR (SELECT count(*) FROM tam_the_lookup_entries e JOIN calculation_rules r ON r.id=e.rule_id
 WHERE r.module='TAM_THE' AND r.rule_version='1.0' AND r.rule_code IN('TT-CONG-DANH-11','TT-CONG-DANH-13'))<>171
 THEN RAISE EXCEPTION 'D01 expected exactly 51+120 career entries before review'; END IF;
END $$;
COMMIT;
